import { Group, Mesh, PlaneGeometry, CylinderGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, DoubleSide } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<Object>} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'FeatureTriptych';

  // ----- constants -----
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const ICON_DIAM = 0.4;
  const ICON_EXTRUDE = 0.05;
  const PADDING = 0.375;
  const ICON_GAP = 0.25;
  const TITLE_GAP = 0.125;
  const BASE_UNIT = 0.25;

  // ----- compute card X positions -----
  const totalWidth = 3 * CARD_W + 2 * GAP;
  const startX = -totalWidth / 2 + CARD_W / 2;
  const cardXs = [startX, startX + CARD_W + GAP, startX + 2 * (CARD_W + GAP)];

  // ----- texture for card background -----
  const texturePromise = config.imageUrl ? ctx.textureLoader.loadTexture(config.imageUrl) : null;

  // ----- parse text items -----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  // Expect items in groups of three: icon, title, body
  const cardsText = [];
  for (let i = 0; i < items.length; i += 3) {
    const icon = items[i];
    const title = items[i + 1];
    const body = items[i + 2];
    cardsText.push({ icon, title, body });
  }

  // ----- keep track of timelines for cleanup -----
  const cleanupTimelines = [];

  // ----- create each card -----
  cardXs.forEach((xPos, idx) => {
    const cardGroup = new Group();
    cardGroup.name = `card${idx + 1}`;
    cardGroup.position.set(xPos, 0.2, 0); // start with y offset for entrance animation
    root.add(cardGroup);

    // ----- plane (background) -----
    const planeGeom = new PlaneGeometry(CARD_W, CARD_H);
    const planeMat = new MeshBasicNodeMaterial({
      color: new Color('#ffffff'),
      transparent: true,
      opacity: 0,
      side: DoubleSide,
    });
    const planeMesh = new Mesh(planeGeom, planeMat);
    planeMesh.name = 'plane';
    cardGroup.add(planeMesh);

    // apply texture when loaded
    if (texturePromise) {
      texturePromise.then((tex) => {
        planeMat.map = tex;
        planeMat.needsUpdate = true;
      });
    }

    // ----- icon seat (disc) -----
    const seatGeom = new CylinderGeometry(ICON_DIAM / 2, ICON_DIAM / 2, ICON_EXTRUDE, 32);
    const seatMat = new MeshStandardNodeMaterial({
      color: new Color('#26262f'),
      metalness: 0.5,
      roughness: 0.55,
      clearcoat: 0.2,
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.6,
    });
    const seatMesh = new Mesh(seatGeom, seatMat);
    seatMesh.name = 'iconSeat';
    seatMesh.rotation.x = Math.PI / 2; // face forward
    // position seat near top edge
    const topY = CARD_H / 2;
    seatMesh.position.set(0, topY - PADDING - ICON_EXTRUDE / 2, 0.01);
    cardGroup.add(seatMesh);

    // ----- glyph text (icon) -----
    const glyphItem = cardsText[idx]?.icon;
    if (glyphItem) {
      const glyph = ctx.fontAtlas.createText(glyphItem.text, {
        fontSize: glyphItem.typography?.fontSize ?? 20,
        color: '#ff2a38',
        align: 'center',
      });
      glyph.name = 'glyph';
      glyph.position.set(0, seatMesh.position.y, 0.02);
      cardGroup.add(glyph);
    }

    // ----- title text -----
    const titleItem = cardsText[idx]?.title;
    if (titleItem) {
      const title = ctx.fontAtlas.createText(titleItem.text, {
        fontSize: titleItem.typography?.fontSize ?? 20,
        color: '#e8ecf2',
        align: 'center',
      });
      title.name = 'title';
      const titleY = seatMesh.position.y - ICON_EXTRUDE / 2 - ICON_GAP - TITLE_GAP - 0.1;
      title.position.set(0, titleY, 0.02);
      cardGroup.add(title);
    }

    // ----- body text -----
    const bodyItem = cardsText[idx]?.body;
    if (bodyItem) {
      const body = ctx.fontAtlas.createText(bodyItem.text, {
        fontSize: bodyItem.typography?.fontSize ?? 13,
        color: '#e8ecf2',
        align: 'center',
      });
      body.name = 'body';
      const bodyY = seatMesh.position.y - ICON_EXTRUDE / 2 - ICON_GAP - TITLE_GAP - 0.2;
      body.position.set(0, bodyY, 0.02);
      cardGroup.add(body);
    }

    // ----- hover interaction -----
    const hoverTimeline = gsap.timeline({ paused: true });
    hoverTimeline
      .to(cardGroup.position, {
        y: 0.06,
        z: 0.12,
        duration: 0.18,
        ease: { type: 'cubicBezier', values: [0.25, 0.46, 0.45, 0.94] },
      })
      .to(
        seatMat,
        {
          emissiveIntensity: 2.2,
          duration: 0.18,
          ease: { type: 'cubicBezier', values: [0.25, 0.46, 0.45, 0.94] },
        },
        0
      );
    cleanupTimelines.push(hoverTimeline);

    cardGroup.userData.handlers = {
      hover: (enter) => {
        if (enter) {
          hoverTimeline.play(0);
        } else {
          hoverTimeline.reverse();
        }
      },
    };
  });

  // ----- entrance stagger animation -----
  const entranceTl = gsap.timeline();
  root.children.forEach((cardGroup, i) => {
    const planeMat = cardGroup.getObjectByName('plane').material;
    entranceTl
      .to(
        planeMat,
        {
          opacity: 1,
          duration: 0.5,
          ease: { type: 'cubicBezier', values: [0.25, 0.46, 0.45, 0.94] },
        },
        i * 0.08
      )
      .to(
        cardGroup.position,
        {
          y: 0,
          duration: 0.5,
          ease: { type: 'cubicBezier', values: [0.25, 0.46, 0.45, 0.94] },
        },
        i * 0.08
      );
  });
  cleanupTimelines.push(entranceTl);

  // ----- cleanup -----
  root.userData.cleanup = () => {
    cleanupTimelines.forEach((tl) => tl.kill());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
